pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Reentrant attacker;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount < type(uint256).max / 2);
        attacker = new Reentrant(c);
        vm.deal(address(attacker), amount);
        vm.prank(address(attacker));
        (bool sent, ) = address(c).call{value: amount}("");
        assertTrue(sent);
        attacker.attack();
        // General rule: any nested (re-entrant) withdraw attempt made from the
        // ETH recipient during a withdraw must fail (locked in P); the mutant
        // zeroes the balance first so the nested call succeeds.
        assertTrue(attacker.reentrySucceeded() == false);
    }
}

contract Reentrant {
    C public target;
    bool public reentrySucceeded;

    constructor(C t) { target = t; }

    function attack() public {
        target.withdraw();
    }

    receive() external payable {
        // re-enter withdraw during the outer send
        try target.withdraw() { reentrySucceeded = true; } catch { reentrySucceeded = false; }
    }
}

