pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        amount = bound(amount, 1, type(uint128).max);

        // deposit via the payable fallback
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool okDep, ) = address(c).call{value: amount}("");
        assertTrue(okDep);
        assertEq(address(c).balance, amount);

        // withdraw everything
        vm.prank(actor);
        bool ok = true;
        try c.withdraw() {} catch { ok = false; }

        // Rule: a successful full withdrawal leaves the contract with no funds.
        // The mutant sends 0 wei (balance already zeroed) so it keeps `amount`.
        assertTrue(ok && address(c).balance == 0);
    }
}

