pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    ReentrantAttacker attacker;

    function setUp() public {
        c = new C();
        attacker = new ReentrantAttacker(c);
    }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1 ether, 100 ether);
        vm.deal(address(attacker), amount);
        attacker.deposit(amount);
        uint256 cStart = address(c).balance;
        attacker.attack();
        // General rule: after a full withdraw by the sole depositor, c has paid out exactly
        // the deposited amount once; c's own balance (funded only via fallback deposits in
        // this scenario, plus whatever we seeded) must never go negative nor pay the same
        // balance twice. The attacker records how many successful payouts it received.
        assertTrue(attacker.payouts() <= amount, "reentrancy paid out more than deposited");
    }
}

contract ReentrantAttacker {
    C public target;
    uint256 public payoutCount;
    uint256 private deposited;

    constructor(C _t) {
        target = _t;
    }

    function deposit(uint256 amt) external payable {
        deposited = amt;
        target.fallback{value: amt}();
    }

    fallback() external payable {
        target.fallback{value: msg.value}();
    }

    function attack() external {
        target.withdraw();
    }

    function payouts() external view returns (uint256) {
        return payoutCount * deposited;
    }

    receive() external payable {
        payoutCount++;
        if (address(target).balance >= deposited && payoutCount < 2) {
            target.withdraw();
        }
    }
}

